@admin_bp.route("/maintenance", methods=["POST"])
@require_role("admin")
def run_maintenance():
    user_id = request.args.get("user_id", "")
    table = "audit_log"
    conn = get_engine().raw_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("DELETE FROM %s WHERE user_id = ?" % table, (user_id,))
        conn.commit()
    finally:
        conn.close()
    return jsonify({"status": "maintenance complete"})

